    }

    function run(uint depositAmount, uint collectAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");
        c.Deposit{value: depositAmount}();
        uint balanceBefore = c.balances(address(this));
        uint contractBalanceBefore = address(c).balance;
        uint selfBalanceBefore = address(this).balance;
        uint minSum = c.MinSum();

        bool reverted;
        try c.Collect{value: 0}(collectAmount) {
