        } else {
            assert(balanceBefore >= minSum && balanceBefore >= collectAmount && balanceAfter == balanceBefore - collectAmount && contractBalanceAfter == contractBalanceBefore - collectAmount && selfBalanceAfter == selfBalanceBefore + collectAmount);
        }
    }

