contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address collector, uint depositAmt, uint am, address logAddr) public payable {
        require(collector != address(0));
        require(logAddr != address(0));

        // Setup: initialize MinSum, set LogFile, mark initialized.
        c.SetMinSum(0);
        c.SetLogFile(logAddr);
        c.Initialized();

        // Deposit from this contract so that the required balance exists.
        require(address(this).balance >= depositAmt);
        c.Deposit{value: depositAmt}();

        // Read before values.
        uint beforeBal = c.balances(address(this));
        uint beforeContractBalance = address(c).balance;

        // Attempt Collect with amount am.
        bool reverted;
        try c.Collect(am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after values.
        uint afterBal = c.balances(address(this));
        uint afterContractBalance = address(c).balance;

        // General rule: if the call succeeded, the caller's public balance drops by exactly am
        // and the contract's Ether balance drops by exactly am.
        assert(reverted || (afterBal == beforeBal - am && afterContractBalance == beforeContractBalance - am));
    }

    receive() external payable {}
}

